import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { randomUUID } from 'node:crypto';

/** Case-insensitive comparison, used for the username unique index and lookups. */
export const CASE_INSENSITIVE = { locale: 'en', strength: 2 } as const;

@Schema({
  collection: 'users',
  timestamps: { createdAt: 'joinDate', updatedAt: 'updatedAt' },
  versionKey: false,
})
export class User {
  /** GUID string, generated by the API (not a Mongo ObjectId). */
  @Prop({ type: String, default: () => randomUUID() })
  _id: string;

  /** Stored as entered; uniqueness is case-insensitive. */
  @Prop({ type: String, required: true, trim: true })
  username: string;

  /** argon2id hash. Never selected unless explicitly requested. */
  @Prop({ type: String, required: true, select: false })
  passwordHash: string;

  @Prop({ type: String, required: true, trim: true, lowercase: true })
  email: string;

  @Prop({ type: String, required: true, trim: true })
  firstName: string;

  @Prop({ type: String, required: true, trim: true })
  lastName: string;

  @Prop({ type: String, default: null })
  pronouns: string | null;

  @Prop({ type: Boolean, required: true, default: true })
  active: boolean;

  /** Set by Mongoose timestamps. */
  joinDate: Date;
  updatedAt: Date;
}

export const UserSchema = SchemaFactory.createForClass(User);

// Usernames and emails stay reserved after a user is deactivated, so these
// indexes cover every document, active or not.
UserSchema.index(
  { username: 1 },
  { unique: true, collation: CASE_INSENSITIVE },
);
UserSchema.index({ email: 1 }, { unique: true });
